import type { z } from "zod";
import type { createPostSchema, updatePostSchema } from "./post.validator.js";
import type { ReactionType } from "../reaction/reaction.types.js";
import type { Post, PostVisibility } from "../../generated/prisma/client.js";

// Every type the Post module owns. See modules/auth/auth.types.ts for the same idea on that side.

// ─── Database row ────────────────────────────────────────────────────────────
// Generated by Prisma from prisma/schema.prisma, so it always matches the posts table.
// (search_vector is Unsupported("tsvector"), so Prisma leaves it out of this type entirely.)
export type { Post, PostVisibility };

// The values the validator accepts. Typed against the Prisma enum, so adding a value to the
// schema without adding it here (or the other way round) is a compile error.
export const POST_VISIBILITIES = ["PUBLIC", "FOLLOWERS", "PRIVATE"] as const satisfies readonly PostVisibility[];

// ─── Service input ───────────────────────────────────────────────────────────

export interface CreatePostData {
  authorId: string;
  body: string;
  visibility: PostVisibility;
}

// undefined = leave unchanged
export interface UpdatePostData {
  body?: string;
  visibility?: PostVisibility;
}

// ─── Resource (the JSON shape clients receive) ───────────────────────────────
// snake_case, like the auth resources.

export interface PostResource {
  id: string;
  author_id: string;
  body: string | null;
  visibility: PostVisibility;
  like_count: number;
  comment_count: number;
  edited_at: Date | null;
  created_at: Date;
  updated_at: Date;
}

// What the controller sends (already validated)
export type CreatePostInput = z.infer<typeof createPostSchema>;
export type UpdatePostInput = z.infer<typeof updatePostSchema>;

// ─── Feed ────────────────────────────────────────────────────────────────────

export interface PostAuthor { id: string; username: string; displayName: string }
// A post with its author included (Prisma `include: { author: { select: { id, username, displayName } } }`).
export type PostWithAuthor = Post & { author: PostAuthor };
// Everything one feed item needs, including what's specific to the viewer.
export interface PostView { post: PostWithAuthor; myReaction: ReactionType | null }
export interface FeedPage { items: PostView[]; nextCursor: string | null }
